-- Anchor window: 2026-03-04 .. 2027-03-03 (anchor 'today' = 2026-09-02, a Wednesday). Shifted to the current week on apply.
-- All wall-clock times America/New_York. Re-runnable: truncates demo tables first.
BEGIN;
SET LOCAL timezone = 'America/New_York';

-- Shift helpers: move the anchor week (Mon 2026-08-31) onto the current week, whole weeks only.
-- Session-scoped (pg_temp); they vanish when the connection closes. pg_temp functions must be called qualified.
CREATE OR REPLACE FUNCTION pg_temp.shift() RETURNS interval LANGUAGE sql STABLE AS
  $$ SELECT (date_trunc('week', current_date)::date - date '2026-08-31') * interval '1 day' $$;
CREATE OR REPLACE FUNCTION pg_temp.s(t timestamp) RETURNS timestamptz LANGUAGE sql STABLE AS
  $$ SELECT (t + pg_temp.shift())::timestamptz $$;
CREATE OR REPLACE FUNCTION pg_temp.d(x date) RETURNS date LANGUAGE sql STABLE AS
  $$ SELECT (x + pg_temp.shift())::date $$;
CREATE OR REPLACE FUNCTION pg_temp.f(t timestamp) RETURNS text LANGUAGE sql STABLE AS
  $$ SELECT to_char(pg_temp.s(t), 'FMDay, FMMonth FMDD at FMHH12:MI AM') $$;

-- Re-runnable: clear demo data. Rules in appointment_transition are schema and are kept.
